export function indexPairs(text: string, words: string[]): number[][] {
  const result: number[][] = [];
  for (const word of words) {
    let start = 0;
    while (true) {
      const idx = text.indexOf(word, start);
      if (idx === -1) {
        break;
      }
      result.push([idx, idx + word.length - 1]);
      start = idx + 1;
    }
  }
  result.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  return result;
}
